solutionCode:
#[derive(Debug, PartialEq)]
pub struct Ponto {
    pub x: i32,
    pub y: i32,
}

pub fn ponto_de(x: i32, y: i32) -> Ponto {
    Ponto { x: x, y: y }
}

pub fn iguais(a: Ponto, b: Ponto) -> bool {
    a == b
}

testsCode:
use desafio::iguais;
use desafio::ponto_de;

#[test]
fn testa_os_dois_pontos_iguais() {
    assert_eq!(iguais(ponto_de(2, 3), ponto_de(2, 3)), true);
}

#[test]
fn testa_os_dois_pontos_trocados() {
    assert_eq!(iguais(ponto_de(2, 3), ponto_de(3, 2)), false);
}
